// Builds a self-contained IIFE of Alibaba page-agent that exposes `window.PageAgent`.
// agodesk injects this bundle into the controlled browser tab via CDP; the in-page
// agent's LLM calls are routed back to AuraGo through a customFetch bridge (see
// src/lib/services/page-agent/). Keeping the artifact vendored avoids any runtime
// CDN dependency. Re-run after bumping the page-agent dependency:
//   node scripts/build-page-agent-bundle.mjs
import { build } from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outfile = path.join(
  root,
  "src",
  "lib",
  "services",
  "page-agent",
  "vendor",
  "page-agent.iife.js",
);

fs.mkdirSync(path.dirname(outfile), { recursive: true });

const banner =
  "/* eslint-disable */\n" +
  "// AUTO-GENERATED by scripts/build-page-agent-bundle.mjs. Do not edit by hand.\n" +
  "// Vendored Alibaba page-agent (MIT) exposed as window.PageAgent.\n";

await build({
  stdin: {
    contents: `import { PageAgent } from "page-agent";\nglobalThis.PageAgent = PageAgent;\n`,
    resolveDir: root,
    loader: "js",
    sourcefile: "page-agent-entry.js",
  },
  bundle: true,
  format: "iife",
  platform: "browser",
  target: ["chrome110"],
  minify: true,
  legalComments: "none",
  banner: { js: banner },
  define: {
    "process.env.NODE_ENV": '"production"',
  },
  outfile,
});

const bytes = fs.statSync(outfile).size;
console.log(`page-agent bundle written: ${path.relative(root, outfile)} (${bytes} bytes)`);
